'use server'

import { cloneVersion as cloneDBVersion } from '@/db'
import type { AddEntry, Entry } from '@/lib/headcode/types'
import {
  addEntryAndSections,
  deleteEntryAndSections,
} from '@/lib/headcode/admin'
import { updateTag } from 'next/cache'

export async function addEntry(
  values: AddEntry,
): Promise<{ entry?: Entry; error?: string }> {
  try {
    const entry = await addEntryAndSections(values)

    updateTag('/headcode/entries')
    return { entry }
  } catch (error) {
    console.error('error adding entry', error)
    return { error: 'Error adding entry. Namespace or key already exists.' }
  }
}

export async function deleteEntry(
  id: number,
): Promise<{ success?: boolean; error?: string }> {
  try {
    await deleteEntryAndSections(id)

    updateTag('/headcode/entries')
    return { success: true }
  } catch (error) {
    console.error('error deleting entry', error)
    return {
      error: 'Failed to delete entry',
    }
  }
}

export async function cloneVersion(
  clone: string,
): Promise<{ success?: boolean; error?: string }> {
  try {
    await cloneDBVersion(clone)
    updateTag('/headcode/entries')

    return { success: true }
  } catch (error) {
    console.error('error cloning database', error)
    return { error: 'Failed to clone database' }
  }
}

'use client'

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog'
import {
  Field,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLabel,
} from '@/components/ui/field'
import { Input } from '@/components/ui/input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Spinner } from '@/components/ui/spinner'
import type { UIEntryType } from '@/lib/headcode/types'
import { useForm } from '@tanstack/react-form'
import { AlertCircleIcon, FileStackIcon } from 'lucide-react'
import { useState } from 'react'
import { z } from 'zod'
import { addEntry } from './actions'
import { useRouter } from 'next/navigation'

const formSchema = z.object({
  namespace: z.string(),
  key: z
    .string()
    .regex(
      /^[a-zA-Z0-9-_]+$/,
      'Key can only contain letters, numbers, dashes, and underscores',
    ),
})

export function DialogAddEntry({
  version,
  dynamicEntries,
}: {
  version: string
  dynamicEntries: UIEntryType[]
}) {
  const [open, setOpen] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [redirectPath, setRedirectPath] = useState<string | null>(null)
  const router = useRouter()

  const form = useForm({
    defaultValues: {
      namespace: dynamicEntries[0].namespace,
      key: '',
    },
    validators: {
      onSubmit: formSchema,
    },
    onSubmit: async ({ value }) => {
      setError(null)

      const { entry: newEntry, error } = await addEntry({
        version,
        namespace: value.namespace,
        key: value.key,
      })

      if (newEntry) {
        form.reset()
        setRedirectPath(`/headcode/section/${newEntry.id}`)
        setOpen(false)
      } else if (error) {
        setError(error)
      }
    },
  })

  const handleAnimationEnd = (e: React.AnimationEvent<HTMLDivElement>) => {
    const target = e.currentTarget
    if (
      !open &&
      redirectPath &&
      target.getAttribute('data-state') === 'closed'
    ) {
      router.push(redirectPath)
      setRedirectPath(null)
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="secondary" size="sm">
          <FileStackIcon className="size-4" />
          Add <span className="hidden sm:inline">dynamic entry</span>
        </Button>
      </DialogTrigger>
      <DialogContent
        className="sm:max-w-[425px]"
        onAnimationEnd={handleAnimationEnd}
      >
        <DialogHeader>
          <DialogTitle>Add entry</DialogTitle>
          <DialogDescription>
            Add a new dynamic entry to Headcode CMS.
          </DialogDescription>
        </DialogHeader>
        {error && (
          <Alert variant="destructive">
            <AlertCircleIcon />
            <AlertTitle>Error adding entry.</AlertTitle>
            <AlertDescription>
              <p>{error}</p>
            </AlertDescription>
          </Alert>
        )}
        <form
          id="add-entry-form"
          onSubmit={(e) => {
            e.preventDefault()
            e.stopPropagation()
            form.handleSubmit()
          }}
        >
          <FieldGroup>
            <form.Field name="namespace">
              {(field) => {
                const isInvalid =
                  field.state.meta.isTouched && !field.state.meta.isValid
                return (
                  <Field data-invalid={isInvalid}>
                    <FieldLabel htmlFor={field.name}>Namespace</FieldLabel>
                    <Select
                      name={field.name}
                      value={field.state.value}
                      onValueChange={field.handleChange}
                      aria-invalid={isInvalid}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select namespace" />
                      </SelectTrigger>
                      <SelectContent>
                        {dynamicEntries.map((entryType) => (
                          <SelectItem
                            key={entryType.namespace}
                            value={entryType.namespace}
                          >
                            {entryType.namespace}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    {isInvalid && (
                      <FieldError errors={field.state.meta.errors} />
                    )}
                  </Field>
                )
              }}
            </form.Field>
            <form.Field name="key">
              {(field) => {
                const isInvalid =
                  field.state.meta.isTouched && !field.state.meta.isValid
                return (
                  <Field data-invalid={isInvalid}>
                    <FieldLabel htmlFor={field.name}>Key</FieldLabel>
                    <Input
                      id={field.name}
                      name={field.name}
                      value={field.state.value}
                      onBlur={field.handleBlur}
                      onChange={(e) => field.handleChange(e.target.value)}
                      aria-invalid={isInvalid}
                      autoComplete="off"
                    />
                    <FieldDescription>
                      Use letters, numbers, dashes, and underscores for the key.
                    </FieldDescription>
                    {isInvalid && (
                      <FieldError errors={field.state.meta.errors} />
                    )}
                  </Field>
                )
              }}
            </form.Field>
          </FieldGroup>
        </form>
        <form.Subscribe
          selector={(state) => [state.canSubmit, state.isSubmitting]}
        >
          {([canSubmit, isSubmitting]) => (
            <DialogFooter>
              <DialogClose asChild>
                <Button variant="outline">Cancel</Button>
              </DialogClose>

              <Button type="submit" form="add-entry-form" disabled={!canSubmit}>
                {isSubmitting && <Spinner />}
                Add Entry
              </Button>
            </DialogFooter>
          )}
        </form.Subscribe>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { Container } from '@/components/headcode/admin/container'
import { Header } from '@/components/headcode/admin/header'
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert'
import { Button } from '@/components/ui/button'
import { AlertCircleIcon } from 'lucide-react'
import { useEffect } from 'react'

export default function Error({
  error,
  reset,
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
  useEffect(() => {
    console.error(error)
  }, [error])

  const dbError = error.message.startsWith('DB_ERROR')
  const unauthorizedError = error.message.startsWith('UNAUTHORIZED')
  const otherError = !dbError && !unauthorizedError

  return (
    <Container>
      <Header />
      <Alert variant="destructive">
        <AlertCircleIcon />
        <AlertTitle>Something went wrong.</AlertTitle>
        <AlertDescription>
          {dbError && (
            <>
              <p>Database error</p>
              <ul className="list-inside list-disc text-sm">
                <li>On a fresh installation, check your setup</li>
                <li>Check your configuration</li>
                <li>Check your database connection</li>
              </ul>
            </>
          )}
          {unauthorizedError && (
            <>
              <p>Unauthorized</p>
              <ul className="list-inside list-disc text-sm">
                <li>You are not authorized to access this page</li>
                <li>Please contact your administrator</li>
              </ul>
            </>
          )}
          {otherError && <p>{error.message ?? 'An unknown error occurred'}</p>}
          <div className="flex justify-end">
            <Button
              variant="destructive"
              className="mt-4"
              onClick={() => reset()}
            >
              Try again
            </Button>
          </div>
        </AlertDescription>
      </Alert>
    </Container>
  )
}

@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

:root {
