const getEntriesColumns = (
  handleEdit: (entry: UIEntry) => void,
  handleDelete: (entry: UIEntry) => void,
): ColumnDef<UIEntry>[] => [
  {
    accessorKey: 'isDynamic',
    header: '',
    cell: ({ row }) => {
      const entry = row.original
      return entry.isDynamic ? <FileStackIcon className="size-4" /> : null
    },
  },
  {
    accessorKey: 'namespace',
    header: ({ column }) => {
      return (
        <Button
          variant="ghost"
          onClick={() => column.toggleSorting(column.getIsSorted() === 'asc')}
        >
          Namespace
        </Button>
      )
    },
  },
  {
    accessorKey: 'key',
    header: ({ column }) => {
      return (
        <Button
          variant="ghost"
          onClick={() => column.toggleSorting(column.getIsSorted() === 'asc')}
        >
          Key
        </Button>
      )
    },
  },
  {
    id: 'actions',
    cell: ({ row }) => {
      const entry = row.original

      return (
        <>
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" className="h-8 w-8 p-0">
                <span className="sr-only">Open menu</span>
                <MoreHorizontal className="h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuItem onClick={() => handleEdit(entry)}>
                Edit entry
              </DropdownMenuItem>
              {entry.isDynamic && (
                <DropdownMenuItem onClick={() => handleDelete(entry)}>
                  Delete entry
                </DropdownMenuItem>
              )}
            </DropdownMenuContent>
          </DropdownMenu>
        </>
      )
    },
  },
]

export function EntriesTable({
  version,
  data,
  entryTypes,
}: {
  version: string
  data: UIEntry[]
  entryTypes: UIEntryType[]
}) {
  const [open, setOpen] = useState(false)
  const [entryToDelete, setEntryToDelete] = useState<UIEntry | null>(null)
  const [isDeleting, setIsDeleting] = useState(false)
  const router = useRouter()

  const handleDelete = (entry: UIEntry) => {
    setEntryToDelete(entry)
    setOpen(true)
  }

  const handleEdit = async (entry: UIEntry) => {
    let id = entry.id
    if (!id) {
      const { entry: newEntry, error } = await addEntry({
        version,
        namespace: entry.namespace,
        key: entry.key,
      })

      if (newEntry) {
        id = newEntry.id
      } else if (error) {
        toast.warning(error)
      }
    }

    if (id) {
      router.push(`/headcode/section/${id}`)
    }
  }

  const columns = getEntriesColumns(handleEdit, handleDelete)

  const handleConfirmDelete = async (e: React.MouseEvent) => {
    e.preventDefault()
    e.stopPropagation()

    if (entryToDelete) {
      setIsDeleting(true)
      if (entryToDelete.id) {
        const { success, error } = await deleteEntry(entryToDelete.id)
        if (success) {
          toast.success('Entry deleted successfully')
        } else if (error) {
          toast.warning(error)
        }
      }

      setIsDeleting(false)
      setOpen(false)
      setEntryToDelete(null)
    }
  }

  return (
    <>
      <EntriesDataTable
        columns={columns}
        data={data}
        entryTypes={entryTypes}
        handleEdit={handleEdit}
      />
      <ConfirmationDialog
        open={open}
        setOpen={setOpen}
        title={`Delete entry ${entryToDelete?.namespace} / ${entryToDelete?.key}?`}
        description={`This action cannot be undone. This will permanently delete the entry ${entryToDelete?.namespace} / ${entryToDelete?.key} from Headcode CMS.`}
        buttonText="Delete entry"
        isSubmitting={isDeleting}
        handleSubmit={handleConfirmDelete}
      />
    </>
  )
}

export function EntriesDataTable<TData, TValue>({
  columns,
  data,
  entryTypes,
  handleEdit,
}: {
  columns: ColumnDef<TData, TValue>[]
  data: TData[]
  entryTypes: UIEntryType[]
  handleEdit: (entry: TData) => void
}) {
  const [sorting, setSorting] = useState<SortingState>([])
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([])
  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    onSortingChange: setSorting,
    getSortedRowModel: getSortedRowModel(),
    onColumnFiltersChange: setColumnFilters,
    getFilteredRowModel: getFilteredRowModel(),
    state: {
      sorting,
      columnFilters,
    },
    initialState: {
      pagination: {
        pageSize: 50,
      },
    },
  })

  return (
    <div>
      <div className="flex items-center pb-4">
        <Select
          value={
            (table.getColumn('namespace')?.getFilterValue() as string) ?? ''
          }
          onValueChange={(value) =>
            table
              .getColumn('namespace')
              ?.setFilterValue(value === '_clear' ? '' : value)
          }
        >
          <SelectTrigger className="min-w-[120px]">
            <SelectValue placeholder="Filter by namespace" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="_clear" className="flex items-center gap-2">
              <XCircleIcon className="size-4" />
              <span>Clear filter</span>
            </SelectItem>
            <SelectSeparator />
            {entryTypes.map((entryType) => (
              <SelectItem
                key={entryType.namespace}
                value={entryType.namespace}
                className="flex items-center gap-2"
              >
                {entryType.dynamic ? (
                  <FileStackIcon className="size-4" />
                ) : (
                  <SquareIcon className="size-4 text-transparent" />
                )}
                <span>{entryType.namespace}</span>
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <div className="overflow-hidden rounded-md border">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => {
                  return (
                    <TableHead key={header.id}>
                      {header.isPlaceholder
                        ? null
                        : flexRender(
                            header.column.columnDef.header,
                            header.getContext(),
                          )}
                    </TableHead>
                  )
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && 'selected'}
                  className="cursor-pointer"
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell
                      key={cell.id}
                      {...(cell.column.id !== 'actions' && {
                        onClick: () => {
                          handleEdit(row.original)
                        },
                      })}
                      className={cn(
                        'px-6',
                        cell.column.id === 'key' && 'w-full',
                        cell.column.id === 'isDynamic' && 'pr-2 pl-6',
                      )}
                    >
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={columns.length}>
                  <Empty>
                    <EmptyHeader>
                      <EmptyMedia variant="icon">
                        <LayoutPanelTopIcon />
                      </EmptyMedia>
                      <EmptyTitle>No content entries found</EmptyTitle>
                    </EmptyHeader>
                  </Empty>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      {table.getPageCount() > 1 && (
        <div className="flex items-center justify-between py-4">
          <Pagination>
            <PaginationContent>
              <PaginationItem>
                <PaginationPrevious
                  isActive={table.getCanPreviousPage()}
                  onClick={() => {
                    if (table.getCanPreviousPage()) {
                      table.previousPage()
                    }
                  }}
                />
              </PaginationItem>

              {table.getPageCount() > 1 && (
                <>
                  {Array.from({ length: table.getPageCount() }).map(
                    (_, index) => (
                      <PaginationItem key={index}>
                        <PaginationLink
                          onClick={() => table.setPageIndex(index)}
                          isActive={
                            index === table.getState().pagination.pageIndex
                          }
                        >
                          {index + 1}
                        </PaginationLink>
                      </PaginationItem>
                    ),
                  )}
                </>
              )}
              <PaginationItem>
                <PaginationNext
                  isActive={table.getCanNextPage()}
                  onClick={() => {
                    if (table.getCanNextPage()) {
                      table.nextPage()
                    }
                  }}
                />
              </PaginationItem>
            </PaginationContent>
          </Pagination>
        </div>
      )}
    </div>
  )
}

'use server'

import {
  deleteSection as deleteDBSection,
  reorderSections as reorderDBSections,
  updateSection as updateDBSection,
} from '@/db'
import type { Section } from '@/lib/headcode/types'
import { updateEntryCache } from '@/lib/headcode/cache'

export async function reorderSections(
  entryId: number,
  items: { id: number; pos: number }[],
): Promise<{ success?: boolean; error?: string }> {
  try {
    await reorderDBSections(items)

    await updateEntryCache(entryId)

    return { success: true }
  } catch (error) {
    console.error('Error reordering section entries', error)
    return { error: 'Error reordering section entries' }
  }
}

export async function updateSection(
  section: Section,
): Promise<{ success?: boolean; error?: string }> {
  try {
    await updateDBSection(section)

    await updateEntryCache(section.entryId)
    return { success: true }
  } catch (error) {
    console.error('Error updating section', error)
    return { error: 'Error updating section' }
  }
}

export async function deleteSection(
  entryId: number,
  sectionId: number,
): Promise<{ success?: boolean; error?: string }> {
  try {
    await deleteDBSection(sectionId)

    await updateEntryCache(entryId)
    return { success: true }
  } catch (error) {
    console.error('Error deleting section', error)
    return { error: 'Error deleting section' }
  }
}

'use client'

import { ConfirmationDialog } from '@/components/headcode/admin/dialogs'
import { useAppForm } from '@/components/headcode/form/app-form'
import TextFieldComponent from '@/components/headcode/form/text-field-component'
import { Button } from '@/components/ui/button'
import {
  Card,
  CardContent,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card'
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from '@/components/ui/collapsible'
import { Field, FieldGroup, FieldLabel } from '@/components/ui/field'
import { Empty, EmptyContent } from '@/components/ui/empty'
import {
  Sortable,
  SortableContent,
  SortableItem,
  SortableItemHandle,
  SortableOverlay,
} from '@/components/ui/sortable'
import { Spinner } from '@/components/ui/spinner'
import type { Entry, Section } from '@/lib/headcode/types'
import { getConfigSection } from '@/lib/headcode/config'
import { getDefaultSectionValues, getSchema } from '@/lib/headcode/fields'
import { ChildFields, FieldProps } from '@/lib/headcode/types'
import { GripVerticalIcon, MinusIcon, PlusIcon, XIcon } from 'lucide-react'
import { useEffect, useRef, useState } from 'react'
import { toast } from 'sonner'
import { deleteSection, updateSection } from './actions'
import type { AppFormInstance } from '@/components/headcode/form/app-form'

export function Form({
  entry,
  section,
  onFormReady,
}: {
  entry: Entry
  section: Section
  onFormReady?: (form: AppFormInstance) => void
}) {
  const [open, setOpen] = useState(false)
  const [isDeleting, setIsDeleting] = useState(false)

  const configSection = getConfigSection(
    entry.namespace,
    entry.key,
    section.name,
  )

  const fields = configSection.fields
  const formSchema = getSchema(fields)
  const defaultValues = getDefaultSectionValues(fields, section.data)

  const form = useAppForm({
    defaultValues,
    validators: {
      onSubmit: formSchema,
    },
    onSubmit: async ({ value }) => {
      const { success, error } = await updateSection({
        ...section,
        data: JSON.stringify(value),
      })
      if (success) {
        // Reset form with saved values to clear dirty state and update defaults
        // In TanStack Form, isDirty is persistent and only clears on reset
        // Passing the saved values ensures the form displays the new state
        form.reset(value)
        toast.success('Section saved successfully')
      } else if (error) {
        toast.warning(error)
      }
    },
  })

  // Reset form to original state when loaded
  useEffect(() => {
    form.reset()
  }, [form])

  // Expose form instance to parent
  useEffect(() => {
    onFormReady?.(form as unknown as AppFormInstance)
  }, [form, onFormReady])

  const handleDeleteSection = () => {
    setOpen(true)
  }

  const handleConfirmDelete = async (e: React.MouseEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setIsDeleting(true)

    const { success, error } = await deleteSection(entry.id, section.id)
    setIsDeleting(false)

    if (success) {
      setOpen(false)
    } else if (error) {
      toast.warning(error)
    }
  }

  const SectionChildFields = ({
    parentKey,
    index,
    child,
    field,
  }: {
    parentKey: string
    index: number
    child: Record<string, unknown>
    field: ChildFields
  }) => {
    return (
      <FieldGroup className="pt-3 pb-5">
        {Object.keys(child).map((childKey) => {
          const childField = field.fields[
            childKey as keyof typeof field.fields
          ] as FieldProps<unknown, unknown>
          return (
            <form.AppField
              key={`${childKey}-${index}`}
              name={`${parentKey}[${index}].${childKey}`}
            >
              {() => (
                <childField.component
                  label={childField.label}
                  description={childField.description ?? undefined}
                  options={childField.options as unknown}
                />
              )}
            </form.AppField>
          )
        })}
      </FieldGroup>
    )
  }

  const SectionArray = ({
    nameKey,
    field,
  }: {
    nameKey: string
    field: ChildFields
  }) => {
    const [openStates, setOpenStates] = useState<Record<number, boolean>>({})
    const [isMounted, setIsMounted] = useState(false)

    const stableIdsRef = useRef<Map<number, string>>(new Map())
    const nextIdRef = useRef(0)
    const lastLengthRef = useRef(0)

    useEffect(() => {
      setIsMounted(true)
    }, [])

    const getFirstTextFieldKey = (): string | null => {
      for (const [childKey, childField] of Object.entries(field.fields)) {
        const component = childField.component
        const isTextField =
          component === TextFieldComponent ||
          (component &&
            typeof component === 'object' &&
            '_payload' in component &&
            (component as { _payload?: { _result?: { default?: unknown } } })
              ._payload?._result?.default === TextFieldComponent)

        if (isTextField) {
          return childKey
        }
      }
      return null
    }

    const firstTextFieldKey = getFirstTextFieldKey()

    return (
      <form.AppField key={nameKey} name={nameKey} mode="array">
        {(formField) => {
          const formFieldValues = formField.state.value as Array<
            Record<string, unknown>
          >

          const currentLength = formFieldValues.length
          if (currentLength !== lastLengthRef.current) {
            const stableIds = stableIdsRef.current

            if (stableIds.size > currentLength) {
              const keysToRemove: number[] = []
              stableIds.forEach((_, key) => {
                if (key >= currentLength) {
                  keysToRemove.push(key)
                }
              })
              keysToRemove.forEach((key) => stableIds.delete(key))
            }

            for (let i = 0; i < currentLength; i++) {
              if (!stableIds.has(i)) {
                stableIds.set(i, `item-${nextIdRef.current++}`)
              }
            }

            lastLengthRef.current = currentLength
          }

          const sortableItems = formFieldValues.map((_, index) => ({
            id: stableIdsRef.current.get(index)!,
          }))

          const handleRemove = (index: number) => {
            formField.removeValue(index)
          }

          const handleSortingValueChange = (items: Array<{ id: string }>) => {
            const idToIndex = new Map<string, number>()
            stableIdsRef.current.forEach((stableId, index) => {
              idToIndex.set(stableId, index)
            })

            const reorderedValues = items.map((item) => {
              const originalIndex = idToIndex.get(item.id)!
              return formFieldValues[originalIndex]
            })

            const newStableIds = new Map<number, string>()
            items.forEach((item, newIndex) => {
              newStableIds.set(newIndex, item.id)
            })
            stableIdsRef.current = newStableIds
            lastLengthRef.current = reorderedValues.length

            formField.setValue(reorderedValues as never)
          }

          const getDefaultItemValue = () => {
            return Object.entries(field.fields).reduce(
              (acc, [key, childField]) => {
                acc[key] = childField.defaultValue
                return acc
              },
              {} as Record<string, unknown>,
            )
          }

          const handleAddItem = (e: React.MouseEvent) => {
            e.preventDefault()
            e.stopPropagation()
            formField.pushValue(getDefaultItemValue() as unknown as never)
          }

          return (
            <div>
              <FieldLabel className="my-3 flex w-full items-center justify-between">
                <div>{field.label}</div>
                <Button variant="secondary" size="sm" onClick={handleAddItem}>
                  <PlusIcon className="size-4" />
                  Add
                </Button>
              </FieldLabel>

              {sortableItems.length === 0 ? (
                <Empty className="bg-muted dark:bg-background p-3 md:p-6">
                  <EmptyContent>
                    <p>No {field.label} found</p>
                    <Button variant="outline" size="sm" onClick={handleAddItem}>
                      <PlusIcon className="size-4" />
                      Add
                    </Button>
                  </EmptyContent>
                </Empty>
              ) : (
                <Sortable
                  value={sortableItems}
                  onValueChange={handleSortingValueChange}
                  getItemValue={(item) => item.id}
                >
                  <SortableContent>
                    {formFieldValues?.map((child, index) => {
                      const stableId =
                        stableIdsRef.current.get(index) || index.toString()
                      return (
                        <SortableItem
                          key={stableId}
                          value={stableId}
                          className="bg-background my-1 overflow-hidden rounded-lg border px-4 dark:border-none"
                          asChild
                        >
                          <Collapsible
                            open={openStates[index] ?? false}
                            onOpenChange={(isOpen) => {
                              setOpenStates((prev) => ({
                                ...prev,
                                [index]: isOpen,
                              }))
                            }}
                          >
                            <div className="flex">
                              <SortableItemHandle asChild>
                                <div className="mr-4 flex-none py-3">
                                  <GripVerticalIcon className="text-muted-foreground pointer-events-none size-4 shrink-0 translate-y-0.5 transition-transform duration-200" />
                                </div>
                              </SortableItemHandle>
                              <CollapsibleTrigger className="grow">
                                <div className="flex w-full items-center justify-between">
                                  <div className="flex items-center gap-2">
                                    {field.label}
                                    {firstTextFieldKey && isMounted && (
                                      <form.AppField
                                        name={`${nameKey}[${index}].${firstTextFieldKey}`}
                                      >
                                        {(textField) => {
                                          const value = textField.state
                                            .value as string
                                          const hasValue =
                                            value &&
                                            typeof value === 'string' &&
                                            value.trim()
                                          if (!hasValue) {
                                            return null
                                          }
                                          return (
                                            <span className="text-muted-foreground/50 hidden max-w-xs truncate md:block">
                                              {value}
                                            </span>
                                          )
                                        }}
                                      </form.AppField>
                                    )}
                                  </div>
                                  <div className="relative size-4 shrink-0">
                                    {(openStates[index] ?? false) ? (
                                      <MinusIcon className="text-muted-foreground absolute inset-0 size-4 transition-opacity duration-200" />
                                    ) : (
                                      <PlusIcon className="text-muted-foreground absolute inset-0 size-4 transition-opacity duration-200" />
                                    )}
                                  </div>
                                </div>
                              </CollapsibleTrigger>
                              <div className="text-muted-foreground/50 hover:text-muted-foreground flex-none">
                                <button
                                  onClick={(e) => {
                                    e.preventDefault()
                                    e.stopPropagation()
                                    handleRemove(index)
                                  }}
                                  className="p-3"
                                >
                                  <XIcon className="pointer-events-none size-4 shrink-0 translate-y-0.5 transition-transform duration-200" />
                                </button>
                              </div>
                            </div>
                            <CollapsibleContent>
                              <SectionChildFields
                                parentKey={nameKey}
                                index={index}
                                child={child}
                                field={field}
                              />
                            </CollapsibleContent>
                          </Collapsible>
                        </SortableItem>
                      )
                    })}
                  </SortableContent>
                  <SortableOverlay>
                    <div className="bg-muted-background overflow-hidden rounded-lg border py-3 dark:border-none">
                      &nbsp;
                    </div>
                  </SortableOverlay>
                </Sortable>
              )}
            </div>
          )
        }}
      </form.AppField>
    )
  }

  const SectionFields = () => (
    <FieldGroup>
      {Object.entries(defaultValues).map(([key, value]) => {
        if (Array.isArray(value)) {
          const field = fields[key as keyof typeof fields] as ChildFields
          return <SectionArray key={key} nameKey={key} field={field} />
        } else {
          const field = fields[key as keyof typeof fields] as FieldProps<
            unknown,
            unknown
          >
          return (
            <form.AppField key={key} name={key}>
              {() => (
                <field.component
                  label={field.label}
                  description={field.description ?? undefined}
                  options={field.options as unknown}
                />
              )}
            </form.AppField>
          )
        }
      })}
    </FieldGroup>
  )

  const SectionSubmitButtons = () => (
    <form.Subscribe selector={(state) => [state.canSubmit, state.isSubmitting]}>
      {([canSubmit, isSubmitting]) => (
        <CardFooter>
          <Field
            orientation="horizontal"
            className="flex w-full items-center justify-between gap-2"
          >
            <div className="flex items-center gap-2">
              <Button
                disabled={!canSubmit}
                type="submit"
                form="edit-section-form"
              >
                {isSubmitting && <Spinner />}
                Save
              </Button>
              <Button
                disabled={!canSubmit}
                type="button"
                variant="outline"
                onClick={() => form.reset()}
              >
                Reset
              </Button>
            </div>
            {!section.pinned && (
              <Button
                type="button"
                variant="outline"
                onClick={handleDeleteSection}
              >
                Delete Section
              </Button>
            )}
          </Field>
        </CardFooter>
      )}
    </form.Subscribe>
  )

  return (
    <>
      <Card className="w-full">
        <CardHeader>
          <CardTitle>{configSection.label || section.name}</CardTitle>
        </CardHeader>
        <CardContent>
          <form
            id="edit-section-form"
            onSubmit={(e) => {
              e.preventDefault()
              e.stopPropagation()
              form.handleSubmit()
            }}
          >
            <SectionFields />
          </form>
        </CardContent>
        <SectionSubmitButtons />
      </Card>
      <ConfirmationDialog
        open={open}
        setOpen={setOpen}
        title={`Delete section ${section.name}?`}
        description={`This action cannot be undone. This will permanently delete the section ${section.name} from this entry.`}
        buttonText="Delete section"
        isSubmitting={isDeleting}
        handleSubmit={handleConfirmDelete}
      />
    </>
  )
}

