import { getSchema, getDefaultValues } from './fields'
import type { Fields, InferSectionData } from './types'

export function parseSectionData<F extends Fields>(
  fields: F,
  sectionData: unknown,
): { data: InferSectionData<F>; isDefault: boolean } {
  const schema = getSchema(fields)
  const defaultValues = getDefaultValues(fields)

  if (sectionData === null || sectionData === undefined) {
    const result = schema.safeParse(defaultValues)
    return {
      data: result.success
        ? (result.data as InferSectionData<F>)
        : (defaultValues as InferSectionData<F>),
      isDefault: true,
    }
  }

  if (
    typeof sectionData === 'object' &&
    !Array.isArray(sectionData) &&
    sectionData !== null
  ) {
    const filteredData: Record<string, unknown> = {}
    Object.keys(fields).forEach((key) => {
      if (key in sectionData) {
        filteredData[key] = (sectionData as Record<string, unknown>)[key]
      } else {
        filteredData[key] = defaultValues[key]
      }
    })

    const result = schema.safeParse(filteredData)
    if (result.success) {
      return {
        data: result.data as InferSectionData<F>,
        isDefault: false,
      }
    }

    console.error('Validation failed, using default values', {
      error: result.error,
      filteredData,
      defaultValues,
    })
    const defaultResult = schema.safeParse(defaultValues)
    return {
      data: defaultResult.success
        ? (defaultResult.data as InferSectionData<F>)
        : (defaultValues as InferSectionData<F>),
      isDefault: true,
    }
  }

  if (typeof sectionData === 'string') {
    let parsedData: unknown
    try {
      parsedData = JSON.parse(sectionData)
    } catch (error) {
      console.error('JSON parsing failed, using default values', {
        error,
        sectionData,
      })
      const defaultResult = schema.safeParse(defaultValues)
      return {
        data: defaultResult.success
          ? (defaultResult.data as InferSectionData<F>)
          : (defaultValues as InferSectionData<F>),
        isDefault: true,
      }
    }

    if (
      parsedData &&
      typeof parsedData === 'object' &&
      !Array.isArray(parsedData) &&
      parsedData !== null
    ) {
      const filteredData: Record<string, unknown> = {}
      Object.keys(fields).forEach((key) => {
        if (key in parsedData) {
          filteredData[key] = (parsedData as Record<string, unknown>)[key]
        } else {
          filteredData[key] = defaultValues[key]
        }
      })

      const result = schema.safeParse(filteredData)
      if (result.success) {
        return {
          data: result.data as InferSectionData<F>,
          isDefault: false,
        }
      }

      console.error(
        'Validation failed after JSON parse, using default values',
        {
          error: result.error,
          filteredData,
          defaultValues,
        },
      )
      const defaultResult = schema.safeParse(defaultValues)
      return {
        data: defaultResult.success
          ? (defaultResult.data as InferSectionData<F>)
          : (defaultValues as InferSectionData<F>),
        isDefault: true,
      }
    }
  }

  console.warn('Unexpected sectionData type, using default values', {
    type: typeof sectionData,
    isArray: Array.isArray(sectionData),
    sectionData,
  })
  const defaultResult = schema.safeParse(defaultValues)
  return {
    data: defaultResult.success
      ? (defaultResult.data as InferSectionData<F>)
      : (defaultValues as InferSectionData<F>),
    isDefault: true,
  }
}

import { z } from 'zod'
import type { Fields, ChildFields } from './types'

const buildChildFieldsSchema = (
  childFields: ChildFields,
): z.ZodArray<z.ZodObject<Record<string, z.ZodType>>> => {
  const childSchema = z.object(
    Object.entries(childFields.fields).reduce(
      (acc, [key, field]) => {
        acc[key] = field.validator
        return acc
      },
      {} as Record<string, z.ZodType>,
    ),
  )
  return z.array(childSchema)
}

export const getSchema = (fields: Fields) => {
  return z.object(
    Object.entries(fields).reduce(
      (acc, [key, value]) => {
        if ('defaultValue' in value) {
          acc[key] = value.validator
        } else {
          acc[key] = buildChildFieldsSchema(value as ChildFields)
        }
        return acc
      },
      {} as Record<string, z.ZodType>,
    ),
  )
}

export const getDefaultValues = (fields: Fields) => {
  return Object.entries(fields).reduce(
    (acc, [key, value]) => {
      acc[key] = 'defaultValue' in value ? value.defaultValue : []
      return acc
    },
    {} as Record<string, unknown>,
  )
}

export const getDefaultSectionValues = (
  fields: Fields,
  data: unknown | null,
) => {
  const defaultValues = getDefaultValues(fields)

  if (data) {
    const parsedData = JSON.parse(data as string)
    Object.entries(parsedData).forEach(([key, value]) => {
      if (key in defaultValues) {
        defaultValues[key] = value
      }
    })
  }

  return defaultValues
}

import { rgbaToThumbHash, thumbHashToDataURL } from 'thumbhash'
import type { ImageSize } from './types'

export const defaultBlurDataURL =
  'data:image/png;base64,'

export const calculateSize = (image: ImageSize, min: ImageSize): ImageSize => {
  const ratio = Math.min(
    Math.max(image.width / min.width, 1.0),
    Math.max(image.height / min.height, 1.0),
  )

  return {
    width: Math.round(image.width / ratio),
    height: Math.round(image.height / ratio),
  }
}

export const calculateImageProps = (image: HTMLImageElement) => {
  const canvas = document.createElement('canvas')
  const context = canvas.getContext('2d')
  let thumbHash: string | null = null

  if (context) {
    const scale = 100 / Math.max(image.width, image.height)
    canvas.width = Math.round(image.width * scale)
    canvas.height = Math.round(image.height * scale)
    context.drawImage(image, 0, 0, canvas.width, canvas.height)
    const pixels = context.getImageData(0, 0, canvas.width, canvas.height)
    const binaryThumbHash = rgbaToThumbHash(
      pixels.width,
      pixels.height,
      pixels.data,
    )
    thumbHash = thumbHashToDataURL(binaryThumbHash)
  }

  return {
    width: image.naturalWidth,
    height: image.naturalHeight,
    blurDataURL: thumbHash ?? defaultBlurDataURL,
  }
}

export const compactNumber = (number: number) => {
  const formatter = Intl.NumberFormat('en', {
    notation: 'compact',
    style: 'unit',
    unit: 'byte',
    unitDisplay: 'narrow',
  })
  return formatter.format(number)
}

export function generateUniqueImageName(name: string) {
  const cleanName = name.replace(/\s+/g, '-').toLowerCase()
  const suffix = Math.floor(Math.random() * Date.now()).toString(36)
  const index = cleanName.lastIndexOf('.')

  return index < 0
    ? `${cleanName}-${suffix}`
    : `${cleanName.slice(0, index)}-${suffix}${cleanName.slice(index)}`
}

