export type InferFieldType<F> =
  F extends FieldProps<infer T, unknown>
    ? T
    : F extends ChildFields
      ? Array<{
          [K in keyof F['fields']]: F['fields'][K] extends FieldProps<
            infer T,
            unknown
          >
            ? T
            : never
        }>
      : never

