export type EditorLinkSelectorProps = {
  open?: boolean
  onOpenChange?: (open: boolean) => void
}

export const EditorLinkSelector = ({
  open: controlledOpen,
  onOpenChange: controlledOnOpenChange,
}: EditorLinkSelectorProps) => {
  const [internalOpen, setInternalOpen] = useState<boolean>(false)
  const [url, setUrl] = useState<string>('')
  const inputReference = useRef<HTMLInputElement>(null)
  const { editor } = useCurrentEditor()
  const previousOpenRef = useRef<boolean>(false)

  // Use controlled state if provided, otherwise use internal state
  const open = controlledOpen ?? internalOpen
  const onOpenChange = controlledOnOpenChange ?? setInternalOpen

  const getUrlFromString = (text: string): string | null => {
    const trimmed = text.trim()

    if (trimmed === '') {
      return null
    }

    // Check if it's a valid absolute URL
    try {
      const url = new URL(trimmed)
      return url.toString()
    } catch {
      // Not an absolute URL, continue checking
    }

    // Check if it's a valid relative URL
    if (
      trimmed.startsWith('/') ||
      trimmed.startsWith('./') ||
      trimmed.startsWith('../') ||
      (!trimmed.includes(' ') &&
        !trimmed.includes('\n') &&
        !trimmed.includes('\t'))
    ) {
      return trimmed
    }

    // Try to convert domain-like strings to https:// URLs
    if (trimmed.includes('.') && !trimmed.includes(' ')) {
      try {
        return new URL(`https://${trimmed}`).toString()
      } catch {
        // If that fails, return null
      }
    }

    return null
  }

  useEffect(() => {
    // Only initialize when popover opens (transitions from closed to open)
    if (open && !previousOpenRef.current && editor) {
      const href = (editor.getAttributes('link') as { href?: string }).href
      startTransition(() => {
        setUrl(href ?? '')
      })
      inputReference.current?.focus()
    }
    previousOpenRef.current = open ?? false
  }, [open, editor])

  if (!editor) {
    return null
  }

  const handleSetLink = () => {
    const href = getUrlFromString(url)

    if (href) {
      editor.chain().focus().setLink({ href }).run()
      onOpenChange(false)
    }
  }

  const handleSubmit: FormEventHandler<HTMLFormElement> = (event) => {
    event.preventDefault()
    event.stopPropagation()
    handleSetLink()
  }

  return (
    <Popover modal onOpenChange={onOpenChange} open={open}>
      <PopoverTrigger asChild>
        <Button
          className="gap-2 rounded-none border-none"
          size="sm"
          type="button"
          variant="ghost"
        >
          <ExternalLinkIcon size={12} />
          <p
            className={cn(
              'decoration-text-muted text-xs underline underline-offset-4',
              {
                'text-primary': editor.isActive('link'),
              },
            )}
          >
            Link
          </p>
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-60 p-0" sideOffset={10}>
        <form className="flex p-1" onSubmit={handleSubmit}>
          <input
            aria-label="Link URL"
            className="bg-background flex-1 p-1 text-sm outline-none"
            onChange={(event) => setUrl(event.target.value)}
            placeholder="Paste a link"
            ref={inputReference}
            type="text"
            value={url}
          />
          {editor.getAttributes('link').href ? (
            <Button
              className="text-destructive hover:bg-destructive-foreground dark:hover:bg-destructive flex h-8 items-center rounded-sm p-1 transition-all"
              onClick={() => {
                editor.chain().focus().unsetLink().run()
                onOpenChange(false)
              }}
              size="icon"
              type="button"
              variant="outline"
            >
              <TrashIcon size={12} />
            </Button>
          ) : (
            <Button
              className="h-8"
              onClick={handleSetLink}
              size="icon"
              type="button"
              variant="secondary"
            >
              <CheckIcon size={12} />
            </Button>
          )}
        </form>
      </PopoverContent>
    </Popover>
  )
}

